\begin{figure}
    \centering
    \begin{tikzpicture}[
        node distance=0.5cm and 0.5cm,
        box/.style={rectangle, draw, align=center, text width=3cm},
        bullet-box/.style={rectangle, draw, align=center, text width=3cm},
        worst-box/.style={rectangle, fill=gray!30, draw=none, text width=6.8cm, align=center},
        stoch-box/.style={rectangle, fill=gray!30, draw=none, text width=3cm, align=center},
        edge/.style={draw, -{Latex}},
    ]
    \begin{scope}[font=\footnotesize]

    \node[box] (main) {\textbf{T\ref{thm:main}:} SEK-SMOD outperforms SRPT-$k$};


    \node[box, below=of main] (any-diff) {\textbf{L\ref{lem:any-diff}:} Positive expected improvement per divergence.};
    \node[box, right=of any-diff] (sek-bridge) {\textbf{L\ref{lem:sek-bridge}} implies empty SEK-SMOD system is a renewal process.};


    \matrix[column sep=0.5cm, row sep=0.5cm] (scenarios) at (0,-3.3) {
    \node[bullet-box, anchor=north] (bad) {\textbf{L\ref{lem:bad}: Bad scenario}\\[4pt]
        \begin{minipage}{\textwidth}
        $\bullet$ Expected improvement: $-O(\epsilon)$\\
        $\bullet$ Probability: $O(\epsilon)$
        \end{minipage}}; &
    \node[bullet-box, anchor=north] (neutral) {\textbf{L\ref{lem:neutral}: Neutral scenario} \\ Expected improvement is nonnegative}; &
    \node[bullet-box, anchor=north] (good) {\textbf{L\ref{lem:good}: Good scenario} \\[4pt]
        \begin{minipage}{\textwidth}
        $\bullet$ Expected improvement: $\Omega(\epsilon)$\\
        $\bullet$ Probability: $\Omega(1)$
        \end{minipage}}; \\
    };

    \node[stoch-box, below=of good] (stoch) {Stochastic arguments \\ (see \Cref{sec:stochastic})};

    \node[worst-box, left=of stoch] (worst) {Worst-case arguments \\ (see \Cref{sec:worst-case})};


    \path[edge] (sek-bridge) -- (main);
    \path[edge] (any-diff) -- (main);

    \path[edge] (neutral) -- (any-diff);
    \path[edge] (bad) -- (any-diff);
    \path[edge] (good) -- (any-diff);

    \path[edge] (worst) -- (bad);
    \path[edge] (worst) -- (neutral);
    \path[edge] (stoch) -- (good);
    \end{scope}
    \end{tikzpicture}
\caption{Diagram of proof of Theorem \ref{thm:main}.}
\Description[Flowchart of the proof: Stochastic arguments in section 5 and worst-case arguments in section 6 underpin the main results.]{Flowchart of the proof: Worst-case arguments in section 6 underpin results for the bad and neutral scenarios, while stochastic arguments underpin results for the good scenario. These results are combined to prove our main results.}
\label{diagram:thm-proof}
\end{figure}

